INSERT INTO `galleries` VALUES (1,'Lan hồ điệp','<p>Lan hồ điệp (Phalaenopsis) là \"nữ hoàng\" các loài hoa lan, nổi bật với vẻ đẹp sang trọng, quý phái tựa cánh bướm, thân đơn thân ngắn, lá to dày và rễ mập<span style=\"background-color:rgb(255,255,255);color:rgb(10,10,10);font-size:16px;\"><span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">. Với màu sắc phong phú (trắng, tím, vàng...) và độ bền cao (2-3 tháng), cây thường nở vào dịp Tết, tượng trưng cho may mắn và thịnh vượng.</span><span class=\"uJ19be notranslate vKEkVd\" style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\"> </span></span></p>',1,0,'thu-vien-hoa/hoa-ly/72df1a52fafe3e61b0750240dc775d59.jpg',1,'published','2025-12-27 02:46:48','2026-01-04 21:33:10'),(2,'Hoa Tulip','<p>Hoa tulip (uất kim hương) là loài cây thân thảo lâu năm, nổi tiếng với hình dáng hoa hình chén đơn giản, rực rỡ sắc màu (trừ xanh dương), mọc đơn độc vào mùa xuân<span style=\"background-color:rgb(255,255,255);color:rgb(10,10,10);font-size:16px;\"><span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">. Nguồn gốc từ Trung Á/Thổ Nhĩ Kỳ, tulip biểu trưng cho tình yêu, sự thanh lịch và được mệnh danh là quốc hoa của Hà Lan.</span><span class=\"uJ19be notranslate vKEkVd\" style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\"> </span></span></p>',1,0,'thu-vien-hoa/hoa-tulip/74854e946373f3d754fb49dd12a33bd5.jpg',1,'published','2025-12-27 02:46:48','2026-01-04 21:27:49'),(3,'Hoa Ly','<p>Hoa ly (bách hợp, lily) là loài hoa ôn đới rực rỡ, được mệnh danh là \"nữ hoàng\", nổi bật với thân thẳng (30-150cm), lá xanh bóng và hương thơm nồng nàn<span style=\"background-color:rgb(255,255,255);color:rgb(10,10,10);font-size:16px;\"><span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">. Hoa có 6 cánh (trắng, hồng, vàng, đỏ), thường nở rộ 6-10 ngày, tượng trưng cho sự thuần khiết, quý phái và tình yêu.</span><span class=\"uJ19be notranslate vKEkVd\" style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\"> </span></span></p>',1,0,'anh-danh-muc-san-pham/hoa-ly-hong-tha-binh.jpg',1,'published','2025-12-27 02:46:48','2026-01-04 21:18:48'),(4,'Hoa hồng','<p><span style=\"background-color:rgb(255,255,255);color:rgb(10,10,10);font-size:16px;\"><span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">Hoa hồng, nữ hoàng của loài hoa, đẹp kiêu sa với nhiều màu sắc, hương thơm quyến rũ, tượng trưng cho tình yêu, sự dịu dàng;</span> <span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">có thân cành nhiều gai nhọn bảo vệ, lá xanh răng cưa và những cánh hoa mỏng manh xếp lớp, phô nhụy vàng óng ả</span> <span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">, thường được trồng để trang trí, làm đẹp không gian và mang lại cảm giác thư thái.</span>  </span></p>',1,0,'thu-vien-hoa/hoa-hong/eb3f945c3ce10e66cb846cce497141ca.jpg',1,'published','2025-12-27 02:46:48','2026-01-04 20:20:21'),(5,'Hoa Hướng Dương','<p>Hoa hướng dương (<a class=\"GI370e\" style=\"background-color:rgb(255,255,255);color:unset;font-family:\'Google Sans\', Arial, sans-serif;font-size:16px;font-style:normal;font-weight:400;text-decoration:underline;word-spacing:0px;\" href=\"https://www.google.com/search?q=Helianthus+annuus&amp;rlz=1C5CHFA_enVN1069VN1069&amp;oq=m%C3%B4+t%E1%BA%A3+v%E1%BB%81+hoa+h%C6%B0%C6%A1ng+sduongqw&amp;gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIJCAEQIRgKGKABMgkIAhAhGAoYoAEyCQgDECEYChigATIJCAQQIRgKGKAB0gEINjQwNGowajeoAgCwAgA&amp;sourceid=chrome&amp;ie=UTF-8&amp;mstk=AUtExfDxwRIo5D0YvQDKA6mqeevjdJgKiw7hYt0eOx2gE2MzMbXF4XcSPC4Rt59SCNd1-wIPnEfC1O-JzxxrNoF_1eh5ySh2CDfe-P8MNN5kcEA9MQEhOSypMl5A2TYUTBOM5DIDXNqM_4_OwuaDnU0011keCMT76Qv4J8EaZc3cHiPJdWvfZVRbojXe-5lrbwNHnQl5&amp;csui=3&amp;ved=2ahUKEwj40aaDt_ORAxW2rVYBHSwqGQoQgK4QegQIARAB\">Helianthus annuus</a><span style=\"background-color:rgb(255,255,255);color:rgb(10,10,10);font-size:16px;\"><span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">) </span></span>là loài cây thân thảo rực rỡ với đặc điểm nổi bật luôn hướng về ánh mặt trời, tượng trưng cho sự sống kiên cường, lạc quan và trung thành<span style=\"background-color:rgb(255,255,255);color:rgb(10,10,10);font-size:16px;\"><span style=\"font-family:\'Google Sans\', Arial, sans-serif;font-style:normal;font-weight:400;word-spacing:0px;\">.</span></span></p>',1,0,'anh-danh-muc-san-pham/hinh-ve-hoa-huong-duong.jpeg',1,'published','2025-12-27 02:46:48','2026-01-04 20:13:40');
/*!40000 ALTER TABLE `galleries` ENABLE KEYS */;
